function shotPoint(t){let p=clamp(t,0,1),ease=1-Math.pow(1-p,1.35),s=shot;return{x:s.sx+(s.ex-s.sx)*ease+Math.sin(p*Math.PI)*s.curl*w*.055,y:s.sy+(s.ey-s.sy)*ease-Math.sin(p*Math.PI)*h*(.065+s.power*.035),r:(Math.min(w*.058,25))*(1-ease*.76),spin:s.spin+p*7}}
function drawShot(){if(!shot)return;let p=clamp((performance.now()-shot.started)/shot.duration,0,1);let here=shotPoint(p);ctx.save();ctx.globalAlpha=.6*(1-p*.45);ctx.strokeStyle='#caff8c';ctx.lineWidth=2;ctx.shadowColor='#b8ff65';ctx.shadowBlur=12;ctx.beginPath();for(let i=0;i<16;i++){let q=shotPoint(Math.max(0,p-i*.012));if(!i)ctx.moveTo(q.x,q.y);else ctx.lineTo(q.x,q.y)}ctx.stroke();ctx.restore();drawBall(here.x,here.y,Math.max(5,here.r),here.spin);ui.progress.style.width=`${Math.round(p*100)}%`;if(p>=1)finishShot()}
function draw(){if(!w||!h)return;ctx.clearRect(0,0,w,h);let sky=ctx.createLinearGradient(0,0,0,h*.4);sky.addColorStop(0,'#142d2a');sky.addColorStop(1,'#36534a');ctx.fillStyle=sky;ctx.fillRect(0,0,w,h*.4);drawAtmosphere();drawCrowd();drawField();drawGoal();drawPlayers();if(state==='flying')drawShot();else if(state!=='dead')groundBall();drawGesture();requestAnimationFrame(draw)}
function kickSound(power){try{let ac=new(window.AudioContext||window.webkitAudioContext)(),o=ac.createOscillator(),g=ac.createGain();o.type='triangle';o.frequency.setValueAtTime(115+power*40,ac.currentTime);o.frequency.exponentialRampToValueAtTime(42,ac.currentTime+.12);g.gain.setValueAtTime(.055,ac.currentTime);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+.14);o.connect(g);g.connect(ac.destination);o.start();o.stop(ac.currentTime+.15);setTimeout(()=>ac.close(),300)}catch(e){}}
function startShot(points,elapsed){if(state!=='ready'||points.length<2)return;let a=points[0],z=points[points.length-1],dx=z.x-a.x,dy=z.y-a.y,len=Math.hypot(dx,dy);if(dy>-50||len<70)return;let max=0,sign=0;for(let p of points){let d=(dx*(p.y-a.y)-dy*(p.x-a.x))/(len||1);if(Math.abs(d)>max){max=Math.abs(d);sign=Math.sign(d)}}let curl=clamp(max/(w*.085),0,1)*sign,speed=len/Math.max(100,elapsed),power=clamp(.32+speed*.43,.34,1);let ex=clamp(w*.5+dx*.74+curl*w*.045,w*.2,w*.8);shot={sx:ball.x,sy:ball.y,ex,ey:h*.35,curl,power,spin:curl*.2,started:performance.now(),duration:clamp(1150-power*330,680,1030)};state='flying';shots++;ui.shots.textContent=shots;ui.kick.classList.add('hidden');ui.progress.style.width='0%';kickSound(power);}
function message(kind,title,detail){ui.toast.className=`toast show ${kind}`;ui.toast.querySelector('strong').textContent=title;ui.toast.querySelector('span').textContent=detail;clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),1250)}
function finishShot(){if(state!=='flying')return;let x=shot.ex,inside=x>w*.315&&x<w*.685,keeper=x>w*.455&&x<w*.545,wall=(x>w*.393&&x<w*.433)||(x>w*.478&&x<w*.522)||(x>w*.567&&x<w*.607);let saved=inside&&(keeper||wall);if(inside&&!saved){goals++;streak++;ui.goals.textContent=goals;if(goals>best){best=goals;localStorage.setItem('curveBest',best);ui.best.textContent=best}message('goal','GOAL!','BEAUTIFULLY BENT')}else if(saved){streak=0;message('saved','DENIED','TRY A CORNER')}else{streak=0;message('saved','JUST WIDE','A LITTLE MORE AIM')}
state='dead';shot=null;ui.eyebrow.textContent=goals?'KEEP IT GOING':'NICE TRY';ui.title.innerHTML=goals?`${goals} ${goals===1?'goal':'goals'} on<br>the board.`:'Find the<br>far corner.';ui.sub.innerHTML='<span class="swipe-icon">↗</span>Swipe again to take another kick.';ui.kick.classList.remove('hidden');setTimeout(()=>{if(state==='dead'){state='ready';ui.progress.style.width='0%'}},900)}
canvas.addEventListener('pointerdown',e=>{if(state!=='ready'||e.clientY<h*.57)return;canvas.setPointerCapture(e.pointerId);pointer={points:[{x:e.clientX,y:e.clientY}],time:performance.now()}});
canvas.addEventListener('pointermove',e=>{if(!pointer)return;let now=performance.now(),lastp=pointer.points[pointer.points.length-1];if(Math.hypot(e.clientX-lastp.x,e.clientY-lastp.y)>2)pointer.points.push({x:e.clientX,y:e.clientY,t:now});if(pointer.points.length>100)pointer.points.shift()});
canvas.addEventListener('pointerup',e=>{if(!pointer)return;pointer.points.push({x:e.clientX,y:e.clientY,t:performance.now()});let elapsed=performance.now()-pointer.time,pts=pointer.points;pointer=null;startShot(pts,elapsed)});
canvas.addEventListener('pointercancel',()=>pointer=null);
$('#reset').addEventListener('click',()=>{goals=shots=streak=0;state='ready';shot=null;pointer=null;ui.goals.textContent=ui.shots.textContent='0';ui.title.innerHTML='Bend it like<br>you mean it.';ui.eyebrow.textContent='Your moment';ui.sub.innerHTML='<span class="swipe-icon">↗</span>Swipe the ball. Faster swipe = more power.<br>Draw a curve to add curl.';ui.progress.style.width='0%';ui.toast.classList.remove('show');ui.kick.classList.remove('hidden')});
window.addEventListener('resize',resize);resize();requestAnimationFrame(draw);
})();
</script></body></html>

